```yaml
name: Merge Queue

on:
  pull_request:
    types:
      - labeled
      - unlabeled
      - synchronize
      - opened
      - edited
      - ready_for_review
      - reopened
      - unlocked
  merge_group:
    types: [checks_requested]

permissions:
  contents: read
  pull-requests: read
  issues: read
  checks: write
  statuses: write

jobs:
  merge-queue:
    if: github.event_name == 'merge_group' || (github.event_name == 'pull_request' && github.event.label.name == 'merge queue')
    runs-on: ubuntu-latest
    steps:
      - name: Merge Queue Status
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.issue.number;

            // Check if PR is in merge queue
            const pr = await github.rest.pulls.get({
              owner,
              repo,
              pull_number: prNumber
            });

            if (pr.data.mergeable_state === 'blocked') {
              console.log('PR is in merge queue');
              return;
            }

            // If not in merge queue, check if it should be added
            const labels = pr.data.labels.map(label => label.name);
            if (!labels.includes('merge queue')) {
              console.log('PR does not have merge queue label');
              return;
            }

            // Add to merge queue
            console.log('Adding PR to merge queue');

            // Update status to indicate PR is queued
            await github.rest.repos.createCommitStatus({
              owner,
              repo,
              sha: pr.data.head.sha,
              state: 'pending',
              description: 'In merge queue',
              context: 'merge-queue'
            });
